        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) {
                r.val = l1.val;
                l1 = l1.next;
            } else if (l2.val < l1.val) {
                r.val = l2.val;
                l2 = l2.next;
            }
            if (l1 != null || l2 != null) {
                r.next = new ListNode();
                r = r.next;
            }
        }

        while (l1 != null) {
            r.val = l1.val;
            l1 = l1.next;
            if (l1 != null) {
                r.next = new ListNode();
                r = r.next;
            }
        }

        while (l2 != null) {
            r.val = l2.val;
            l2 = l2.next;
            if (l2 != null) {
                r.next = new ListNode();
                r = r.next;
            }
        }

        return result;
    }
}

